update public.burial_record br set inscription = 'A beloved patriarch, storyteller, and grandfather whose quiet wisdom and steady faith guided generations. Forever resting in God''s eternal peace.' from public.deceased d where br.deceased_id = d.deceased_id and lower(regexp_replace(btrim(d.display_name), '\s+', ' ', 'g')) = 'tomas kuwento' and br.inscription is null;
